{"implementation":"def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    raw = case['distances']
    edges = []
    for u, v, d in raw:
        if u < v:
            a, b = u, v
        else:
            a, b = v, u
        w = max(core[a], core[b], d)
        edges.append((w, a, b))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst = []
    total = 0.0
    n_expected = len(nodes) - 1
    for w, a, b in edges:
        if union(a, b):
            mst.append([a, b, w])
            total += w
            if len(mst) == n_expected:
                break
    if len(mst) != n_expected:
        return {"error": "disconnected"}
    return {"edges": mst, "total_weight": total}
"}
